/**
 * @brief 从字符位图数据中获取指定坐标的像素值（紧凑位图，高位在前）
 * @param data      字符数据起始地址
 * @param x         列坐标 (0 ~ width-1)
 * @param y         行坐标 (0 ~ height-1)
 * @param width     字符宽度
 * @return 1（前景）或 0（背景）
 */
int GetPixel_FromCustomBitmap(const uint8_t *data, int x, int y, int width)
{
    int bit_pos = y * width + x;            // 总位数偏移
    int byte_idx = bit_pos / 8;              // 字节索引
    int bit_shift = 7 - (bit_pos % 8);       // 高位在前，bit7 对应最左像素
    // 如果取模工具实际为低位在前，请将 bit_shift 改为 bit_pos % 8
    return (data[byte_idx] >> bit_shift) & 1;
}

#ifdef ENABLE_LCD_CUSTOM_BITMAP
/**
 * @brief 获取字符在字库映射表中的索引
 * @param charset 字库映射表（Unicode数组或char*字符串）
 * @param unicode 要查找的Unicode值
 * @param count 映射表中字符数量
 * @return 索引，-1 表示未找到
 */
int FindCharIndex(const uint16_t *charset, uint16_t unicode, uint16_t count)
{
    if (charset == NULL || count == 0) {
        return -1;
    }

    // 对于ASCII字符（0-127），尝试在char*字符串中查找
    if (unicode <= 0x7F) {
        char c = (char)unicode;
        const char *char_charset = (const char *)charset;
        for (int i = 0; i < count; i++) {
            if (char_charset[i] == c) {
                return i;
            }
        }
    }
    // 对于非ASCII字符(中文)，在Unicode数组中查找
    else {
        for (int i = 0; i < count; i++) {
            if (charset[i] == unicode) {
                return i;
            }
        }
    }
    return -1;
}

/**
 * @brief 根据Unicode字符获取对应的字库信息
 * @param unicode Unicode字符
 * @return 对应的字库信息指针，NULL表示未找到
 */
CustomBitmapInfo_st* GetCustomFontByUnicode(uint16_t unicode)
{
    // ASCII字符
    if (unicode <= 0x7F) {
        char c = (char)unicode;
        // 数字
        if (c >= '0' && c <= '9') {
            return &number_fontsinfo;
        }
        // 大写字母
        else if (c >= 'A' && c <= 'Z') {
            return &letter_fontsinfo;
        }
        // 小写字母
        else if (c >= 'a' && c <= 'z') {
            return &letter_fontsinfo;
        }
        // 符号
        else if (strchr(symbol_charset, c) != NULL) {
            return &symbol_fontsinfo;
        }
    }
    // 中文（这里简化处理，实际应该根据Unicode范围判断）
    else {
        // 由于中文字符集是硬编码的，这里需要特殊处理
        // 暂时返回中文字库，后续可以根据实际情况优化
        return &chinese_fontsinfo;
    }
    return NULL;
}

/**
 * @brief 计算Unicode字符串宽度，自动选择不同字库
 * @param unicode Unicode字符串数组
 * @return 字符串宽度
 */
int Calc_StringWidth_Auto_Unicode(const uint16_t *unicode)
{
    if (unicode == NULL) {
        return 0;
    }

    int totalWidth = 0;
    for (int i = 0; unicode[i] != 0; i++) {
        CustomBitmapInfo_st* font = GetCustomFontByUnicode(unicode[i]);
        if (font != NULL) {
            totalWidth += font->CharWith;
        }
    }
    return totalWidth;
}

/**
 * @brief 计算Unicode字符串高度，自动选择不同字库
 * @param unicode Unicode字符串数组
 * @return 字符串高度
 */
int Calc_StringHeight_Auto_Unicode(const uint16_t *unicode)
{
    if (unicode == NULL) {
        return 0;
    }

    int maxHeight = 0;
    for (int i = 0; unicode[i] != 0; i++) {
        CustomBitmapInfo_st* font = GetCustomFontByUnicode(unicode[i]);
        if (font != NULL && font->CharHeight > maxHeight) {
            maxHeight = font->CharHeight;
        }
    }
    return maxHeight;
}
#endif
